import { slugifyTitle } from '../../data/card_naming'
import type { CardSeparator } from '../../data/card_identifiers'
import { getElectronActionBridge, type WorktreeDiffResult } from '../../data/electron_action_bridge'
import type {
    Card,
    ProjectReference,
    ProjectSnapshot,
    StorageService,
    WorktreeRecord,
    WorktreeState,
    WorktreeStatus,
} from '../../data/data_types'
import { register } from '../service_injector'

interface WorktreeServiceDependencies {
    assignCardWorktree: (path: string, worktree: number, branch: string) => void
    cardSeparatorProvider: () => CardSeparator
    clearCardBranch: (path: string) => void
    flushPendingChanges: () => Promise<void>
    projectFolderProvider: () => string
    projectProvider: () => ProjectReference | null
    snapshotProvider: () => ProjectSnapshot | null
    storageProvider: () => StorageService | null
    unassignCardWorktree: (path: string) => void
}

/** Same outgoing-status condition used by worktree integration and diff controls. */
export function isWorktreeIntegratable(record: WorktreeRecord | null | undefined) {
    return !!record?.valid && (record.status.dirty || record.status.baseAhead > 0)
}

export class WorktreeService extends EventTarget {
    private adding = false
    private assignCardWorktreeValue: ((path: string, worktree: number, branch: string) => void) | null = null
    private cardSeparatorProvider: (() => CardSeparator) | null = null
    private clearCardBranchValue: ((path: string) => void) | null = null
    private error: string | null = null
    private flushPendingChanges: (() => Promise<void>) | null = null
    private pendingAssignments = new Map<number, string>()
    private preparingCardPaths = new Set<string>()
    private preparingProjectWorktree = false
    private projectActionWorktree: number | null = null
    private primaryStatus: WorktreeStatus | null = null
    private projectFolderProvider: (() => string) | null = null
    private projectProvider: (() => ProjectReference | null) | null = null
    private records: WorktreeRecord[] = []
    private snapshotProvider: (() => ProjectSnapshot | null) | null = null
    private storageProvider: (() => StorageService | null) | null = null
    private subscriptionCleanup: (() => void) | null = null
    private unassignCardWorktreeValue: ((path: string) => void) | null = null

    constructor() {
        super()
        register('worktreeService', this)
    }

    getRecords() {
        return this.records
    }

    getProjectActionWorktree() {
        return this.projectActionWorktree
    }

    getPrimaryStatus() {
        return this.primaryStatus
    }

    /** The branch linked worktrees are rebased onto; null before a project is open. */
    getProjectBranch() {
        return this.projectProvider?.()?.branch ?? null
    }

    getError() {
        return this.error
    }

    isAdding() {
        return this.adding
    }

    isPreparingCard(path: string) {
        return this.preparingCardPaths.has(path)
    }

    isPreparingProjectWorktree() {
        return this.preparingProjectWorktree
    }

    isWorktreeAvailableForCard(worktree: number, cardPath: string) {
        const pendingOwner = this.pendingAssignments.get(worktree)
        if (pendingOwner && pendingOwner !== cardPath) return false

        return !this.activeCards().some((card) => card.path !== cardPath && card.header.worktree === worktree)
    }

    /** Whether card has same valid outgoing worktree state required by integration. */
    canIntegrateCardWorktree(path: string) {
        const card = this.findCard(path)
        const worktree = card?.header.worktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0 || card?.header.worktreeError) return false
        const record = this.records[worktree - 1]

        return isWorktreeIntegratable(record)
    }

    /** Load current diff for card's assigned worktree without changing operation state. */
    async generateCardWorktreeDiff(path: string): Promise<WorktreeDiffResult> {
        const { worktree } = this.requireCardOperation(path)
        if (!this.canIntegrateCardWorktree(path)) throw new Error('Card worktree has no changes to integrate')
        const bridge = getElectronActionBridge()
        if (!bridge?.generateWorktreeDiff) throw new Error('Worktree diff requires Electron local mode')

        return bridge.generateWorktreeDiff({ worktree })
    }

    /** Whether the active storage backend can list worktrees (local desktop or a remote-controlled desktop). */
    isSupported() {
        return !!this.storageProvider?.()?.onWorktreesChanged
    }

    init(dependencies: WorktreeServiceDependencies) {
        this.subscriptionCleanup?.()
        this.assignCardWorktreeValue = dependencies.assignCardWorktree
        this.cardSeparatorProvider = dependencies.cardSeparatorProvider
        this.clearCardBranchValue = dependencies.clearCardBranch
        this.flushPendingChanges = dependencies.flushPendingChanges
        this.projectFolderProvider = dependencies.projectFolderProvider
        this.projectProvider = dependencies.projectProvider
        this.snapshotProvider = dependencies.snapshotProvider
        this.storageProvider = dependencies.storageProvider
        this.unassignCardWorktreeValue = dependencies.unassignCardWorktree
        this.clear()
        this.subscriptionCleanup = dependencies.storageProvider()?.onWorktreesChanged?.((state) => this.handleState(state)) ?? null
    }

    clear() {
        this.projectActionWorktree = null
        this.primaryStatus = null
        this.error = null
        this.records = []
        this.dispatchChanged()
    }

    setProjectActionWorktree(worktree: number | null) {
        if (worktree !== null) {
            if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid project worktree index: ${String(worktree)}`)
            const record = this.records[worktree - 1]
            if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
            if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)
        }
        if (this.projectActionWorktree === worktree) return

        this.projectActionWorktree = worktree
        this.dispatchChanged()
    }

    async setCardWorktree(path: string, worktree: number | null) {
        const card = this.requireCard(path)
        if (card.header.worktree === worktree && !card.header.worktreeError) return
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree preparation is already in progress for ${path}`)

        if (worktree === null) {
            if (card.header.worktreeError || card.header.worktree === null || card.header.worktree === undefined) {
                this.requireUnassignmentWriter()(path)
                return
            }

            const storage = this.requireStorage()
            if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')
            const project = this.requireProject()
            this.startCardOperation(path)
            try {
                await storage.parkWorktree({ project, worktree: card.header.worktree })
                this.requireUnassignmentWriter()(path)
            } finally {
                this.finishCardOperation(path)
            }

            return
        }

        this.requireValidRecord(worktree)
        if (!this.isWorktreeAvailableForCard(worktree, path)) throw new Error(`Worktree ${worktree} is already assigned to another active card`)

        const storage = this.requireStorage()
        if (!storage.prepareWorktree) throw new Error('Worktree preparation requires Electron local mode')
        const project = this.requireProject()
        const branchName = slugifyTitle(`${card.header.id}-${card.header.title}`, this.requireCardSeparator())
        const request = { branchName, project, worktree }
        this.pendingAssignments.set(worktree, path)
        this.startCardOperation(path)
        try {
            await storage.prepareWorktree(request)
            if (this.requireProject() !== project) throw new Error('Opened project changed during worktree preparation')

            this.requireAssignmentWriter()(path, worktree, branchName)
        } finally {
            this.pendingAssignments.delete(worktree)
            this.finishCardOperation(path)
        }
    }

    async refresh() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.refreshWorktrees) throw new Error('Refreshing worktrees requires Electron local mode')
        await storage.refreshWorktrees(project)
    }

    getCardCommitMessage(path: string) {
        const card = this.requireCard(path)

        return `${card.header.id}: ${card.header.title}`
    }

    async commitCardWorktree(path: string, message: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    async integrateCardWorktree(path: string, deleteBranch: boolean) {
        const { card, project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')
        if (!card.header.internalId) throw new Error(`Cannot integrate card without an internal ID: ${path}`)
        const branch = card.header.branch
        if (deleteBranch && !branch) throw new Error(`Cannot delete branch without stored branch identity: ${path}`)
        if (deleteBranch && !storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')
        if (deleteBranch && !storage.deleteLocalBranch) throw new Error('Local branch deletion requires Electron local mode')
        const projectFolder = this.requireProjectFolder()

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            await storage.integrateWorktree({ cardInternalId: card.header.internalId, project, projectFolder, worktree })
            if (deleteBranch && branch) {
                try {
                    if (!storage.parkWorktree || !storage.deleteLocalBranch) throw new Error('Branch cleanup is not available')
                    await storage.parkWorktree({ project, worktree })
                    this.requireUnassignmentWriter()(path)
                    await storage.deleteLocalBranch(project, branch)
                    this.requireBranchClearer()(path)
                } catch (error) {
                    const message = error instanceof Error ? error.message : String(error)
                    throw new Error(`Worktree integrated, but branch cleanup failed: ${message}`, { cause: error })
                }
            }
        } finally {
            this.finishCardOperation(path)
        }
    }

    async updateCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startCardOperation(path)
        try {
            await this.requirePendingChangesFlusher()()
            await storage.rebaseWorktree({ project, worktree })
        } finally {
            this.finishCardOperation(path)
        }
    }

    getProjectCommitMessage() {
        return `Update ${this.getProjectBranch() ?? 'worktree'}`
    }

    async commitProjectWorktree(message: string) {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.commitWorktree) throw new Error('Worktree commits require Electron local mode')

        this.startProjectOperation()
        try {
            await storage.commitWorktree({ message, project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async integrateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.integrateWorktree) throw new Error('Worktree integration requires Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            await storage.integrateWorktree({ project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async updateProjectWorktree() {
        const { project, storage, worktree } = this.requireProjectOperation()
        if (!storage.rebaseWorktree) throw new Error('Worktree updates require Electron local mode')

        this.startProjectOperation()
        try {
            await this.requirePendingChangesFlusher()()
            await storage.rebaseWorktree({ project, worktree })
        } finally {
            this.finishProjectOperation()
        }
    }

    async discardAndUnassignCardWorktree(path: string) {
        const { project, storage, worktree } = this.requireCardOperation(path)
        if (!storage.discardWorktreeChanges) throw new Error('Discarding worktree changes requires Electron local mode')
        if (!storage.parkWorktree) throw new Error('Worktree parking requires Electron local mode')

        this.startCardOperation(path)
        try {
            await storage.discardWorktreeChanges({ project, worktree })
            await storage.parkWorktree({ project, worktree })
            this.requireUnassignmentWriter()(path)
        } finally {
            this.finishCardOperation(path)
        }
    }

    async add() {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.addWorktree) throw new Error('Worktree creation requires Electron local mode')
        if (this.adding) throw new Error('Worktree creation is already in progress')

        this.adding = true
        this.dispatchChanged()
        try {
            const added = await storage.addWorktree(project)

            return added
        } finally {
            this.adding = false
            this.dispatchChanged()
        }
    }

    async remove(index: number) {
        const storage = this.requireStorage()
        const project = this.requireProject()
        if (!storage.removeWorktree) throw new Error('Worktree removal requires Electron local mode')
        if (!Number.isInteger(index) || index < 0 || index >= this.records.length) throw new Error(`Invalid worktree list index: ${index}`)

        await storage.removeWorktree(project, this.records[index].path)
    }

    private requireProject() {
        const project = this.projectProvider?.()
        if (!project) throw new Error('Cannot save worktrees before a project is open')

        return project
    }

    private handleState(state: WorktreeState) {
        const project = this.projectProvider?.()
        if (!project || !state.project || project.id !== state.project.id || project.branch !== state.project.branch) return
        const recordsChanged = JSON.stringify(this.records) !== JSON.stringify(state.records)
        const primaryStatusChanged = JSON.stringify(this.primaryStatus) !== JSON.stringify(state.primaryStatus)
        if (!recordsChanged && !primaryStatusChanged && this.error === state.error) return

        if (recordsChanged) this.records = state.records
        if (primaryStatusChanged) this.primaryStatus = state.primaryStatus
        this.error = state.error
        this.dispatchChanged()
    }

    private activeCards() {
        return this.snapshotProvider?.()?.activeCards ?? []
    }

    private startCardOperation(path: string) {
        if (this.preparingCardPaths.has(path)) throw new Error(`Worktree operation is already in progress for ${path}`)

        this.preparingCardPaths.add(path)
        this.dispatchChanged()
    }

    private finishCardOperation(path: string) {
        this.preparingCardPaths.delete(path)
        this.dispatchChanged()
    }

    private requireCardOperation(path: string) {
        const card = this.requireCard(path)
        const snapshot = this.snapshotProvider?.()
        if (!snapshot) throw new Error('Worktree project snapshot is not initialized')
        const worktree = card.header.worktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error(`Card has no valid worktree assignment: ${path}`)

        this.requireValidRecord(worktree)

        return { card, project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private startProjectOperation() {
        if (this.preparingProjectWorktree) throw new Error('Worktree operation is already in progress for the project')

        this.preparingProjectWorktree = true
        this.dispatchChanged()
    }

    private finishProjectOperation() {
        this.preparingProjectWorktree = false
        this.dispatchChanged()
    }

    private requireProjectOperation() {
        const worktree = this.projectActionWorktree
        if (!Number.isInteger(worktree) || !worktree || worktree <= 0) throw new Error('No worktree is assigned to the project')

        this.requireValidRecord(worktree)

        return { project: this.requireProject(), storage: this.requireStorage(), worktree }
    }

    private requireAssignmentWriter() {
        if (!this.assignCardWorktreeValue) throw new Error('Worktree card assignment is not initialized')

        return this.assignCardWorktreeValue
    }

    private requireBranchClearer() {
        if (!this.clearCardBranchValue) throw new Error('Worktree card branch cleanup is not initialized')

        return this.clearCardBranchValue
    }

    private requireUnassignmentWriter() {
        if (!this.unassignCardWorktreeValue) throw new Error('Worktree card unassignment is not initialized')

        return this.unassignCardWorktreeValue
    }

    private requireProjectFolder() {
        const projectFolder = this.projectFolderProvider?.()
        if (typeof projectFolder !== 'string') throw new Error('Worktree project folder is not initialized')

        return projectFolder
    }

    private requireCard(path: string): Card {
        const card = this.findCard(path)
        if (!card) throw new Error(`Cannot assign a worktree to an unknown card: ${path}`)

        return card
    }

    private findCard(path: string) {
        const snapshot = this.snapshotProvider?.()
        const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

        return cards.find((candidate) => candidate.path === path)
    }

    private requireCardSeparator() {
        const cardSeparator = this.cardSeparatorProvider?.()
        if (!cardSeparator) throw new Error('Worktree card separator is not initialized')

        return cardSeparator
    }

    private requireValidRecord(worktree: number) {
        if (!Number.isInteger(worktree) || worktree <= 0) throw new Error(`Invalid card worktree index: ${String(worktree)}`)
        const record = this.records[worktree - 1]
        if (!record) throw new Error(`Configured worktree ${worktree} does not exist`)
        if (!record.valid) throw new Error(`Configured worktree ${worktree} is invalid: ${record.error}`)

        return record
    }

    private requireStorage() {
        const storage = this.storageProvider?.()
        if (!storage) throw new Error('Worktree service storage is not initialized')

        return storage
    }

    private requirePendingChangesFlusher() {
        if (!this.flushPendingChanges) throw new Error('Worktree pending-change flusher is not initialized')

        return this.flushPendingChanges
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent('changed'))
    }
}

export const worktreeService = new WorktreeService()

import { Box, IconButton, Menu, MenuItem, Tooltip, Typography } from '@mui/material'
import ArrowDown from 'mdi-material-ui/ArrowDown'
import ArrowUp from 'mdi-material-ui/ArrowUp'
import SourceBranch from 'mdi-material-ui/SourceBranch'
import { useState } from 'react'
import type { MouseEvent } from 'react'
import type { WorktreeRecord } from '../data/data_types'
import { dialogService } from '../services/dialog_service'
import { configService } from '../services/config/config_service'
import { isWorktreeIntegratable, worktreeService } from '../services/project/worktree_service'
import { useConfigValueOrFallback } from './hooks/use_config_value'
import { useWorktreeSelectorState } from './hooks/use_worktree_selector_state'
import { WorktreeCommitDialog } from './worktree_commit_dialog'
import { WorktreeIntegrationDialog } from './worktree_integration_dialog'
import { WorktreeUnassignDialog } from './worktree_unassign_dialog'
import { cardBodyPopoverService } from './card_view/card_body_popover_service'

export interface WorktreeAssignment {
    worktree?: number | null
    worktreeError?: string | null
    worktreeValue?: string | null
}

export type WorktreeAssignmentTarget = { kind: 'card', path: string } | { kind: 'project' }
type CommitAction = 'commit' | 'integrate' | 'update'

interface WorktreeSelectorProps {
    assignment: WorktreeAssignment
    assignmentTarget: WorktreeAssignmentTarget
    disabled?: boolean
    labelPrefix?: string
    primaryPath: string | null
}

function assignmentState(assignment: WorktreeAssignment, worktrees: WorktreeRecord[]) {
    if (assignment.worktreeError) {
        return { error: assignment.worktreeError, folder: 'invalid assignment', value: assignment.worktreeValue ?? '?' }
    }
    const worktree = assignment.worktree ?? null
    if (worktree === null) return { error: null, folder: null, value: 'P' }

    const record = worktrees[worktree - 1]
    if (!record) return { error: `Configured worktree ${worktree} does not exist`, folder: 'missing folder', value: String(worktree) }
    if (!record.valid) return { error: `${record.path}: ${record.error}`, folder: record.path, value: String(worktree) }

    return { error: null, folder: record.path, value: String(worktree) }
}

/** Shared worktree assignment button and menu used by cards and action popups. */
export function WorktreeSelector(props: WorktreeSelectorProps) {
    const { assignment, assignmentTarget, disabled = false, labelPrefix, primaryPath } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [commitMessage, setCommitMessage] = useState('')
    const [commitAction, setCommitAction] = useState<CommitAction>('commit')
    const [commitDialogOpen, setCommitDialogOpen] = useState(false)
    const [integrationDialogOpen, setIntegrationDialogOpen] = useState(false)
    const [unassignDialogOpen, setUnassignDialogOpen] = useState(false)
    const deleteBranchPreference = useConfigValueOrFallback('react.deleteBranchAfterIntegration', false)
    const cardPath = assignmentTarget.kind === 'card' ? assignmentTarget.path : null
    const assignedWorktree = assignment.worktree ?? null
    const {
        preparing,
        projectDirty: hasPendingProjectChanges,
        record: assignedRecord,
        records: worktrees,
    } = useWorktreeSelectorState({ assignedWorktree, cardPath })
    const selectorDisabled = disabled || preparing
    const state = assignmentState(assignment, worktrees)
    const hasActiveCardWorktree = assignmentTarget.kind === 'card' && assignedWorktree !== null
        && !state.error && !!assignedRecord?.valid
    const hasActiveProjectWorktree = assignmentTarget.kind === 'project' && assignedWorktree !== null
        && !state.error && !!assignedRecord?.valid
    const canCommit = !!assignedRecord?.status.dirty
    const hasOutgoingChanges = !!assignedRecord
        && (assignedRecord.status.dirty || assignedRecord.status.baseAhead > 0)
    const canIntegrate = isWorktreeIntegratable(assignedRecord)
    const hasIncomingChanges = !!assignedRecord && (hasPendingProjectChanges || assignedRecord.status.baseBehind > 0)
    const hasWorktreeChanges = hasOutgoingChanges || hasIncomingChanges
    const projectBranch = worktreeService.getProjectBranch()
    const folder = state.folder ?? primaryPath ?? 'Primary'
    const assignmentDescription = state.error
        ? `Worktree assignment error: ${state.error}`
        : state.value === 'P'
            ? `Primary worktree${primaryPath ? `: ${primaryPath}` : ''}`
            : `Worktree ${state.value}: ${folder}`
    const baseName = projectBranch ?? 'the project branch'
    const statusParts = assignedRecord
        ? [
            `dirty ${assignedRecord.status.dirty ? 'yes' : 'no'}`,
            `project changes pending ${hasPendingProjectChanges ? 'yes' : 'no'}`,
            `ahead of ${baseName} ${assignedRecord.status.baseAhead}`,
            `behind ${baseName} ${assignedRecord.status.baseBehind}`,
        ]
        : []
    const worktreeStatusDescription = statusParts.length > 0 ? statusParts.join('; ') : null
    const descriptions = [assignmentDescription, worktreeStatusDescription].filter((value) => value !== null)
    const tooltip = descriptions.join('. ')
    const statusLabel = worktreeStatusDescription ? `; ${worktreeStatusDescription}` : ''
    const label = labelPrefix
        ? `${labelPrefix}: ${folder}${statusLabel}`
        : `${assignmentDescription}${statusLabel}`

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        setAnchorElement(event.currentTarget)
    }
    const handleClose = () => setAnchorElement(null)
    const assignWorktree = async (worktree: number | null) => {
        try {
            if (assignmentTarget.kind === 'project') worktreeService.setProjectActionWorktree(worktree)
            else await worktreeService.setCardWorktree(assignmentTarget.path, worktree)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
        }
    }
    const handlePrimary = async () => {
        handleClose()
        if (hasActiveCardWorktree) {
            try {
                if (hasOutgoingChanges) {
                    if (!assignedRecord?.status.dirty) {
                        await worktreeService.integrateCardWorktree(assignmentTarget.path, false)
                        await worktreeService.setCardWorktree(assignmentTarget.path, null)
                        return
                    }
                    setCommitMessage(worktreeService.getCardCommitMessage(assignmentTarget.path))
                    setUnassignDialogOpen(true)
                    return
                }
                await worktreeService.setCardWorktree(assignmentTarget.path, null)
                return
            } catch (error) {
                if (worktreeService.getRecords()[assignedWorktree - 1]?.status.dirty) {
                    setCommitMessage(worktreeService.getCardCommitMessage(assignmentTarget.path))
                    setUnassignDialogOpen(true)
                    return
                }
                dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
                return
            }
        }
        await assignWorktree(null)
    }
    const handleWorktree = async (event: MouseEvent<HTMLElement>) => {
        try {
            const worktree = Number.parseInt(event.currentTarget.dataset.worktree ?? '', 10)
            if (!Number.isInteger(worktree)) throw new Error('Missing worktree menu index')

            handleClose()
            await assignWorktree(worktree)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not update worktree assignment' })
        }
    }
    const getCommitMessage = () => (assignmentTarget.kind === 'card'
        ? worktreeService.getCardCommitMessage(assignmentTarget.path)
        : worktreeService.getProjectCommitMessage())
    const handleCommitMenu = () => {
        handleClose()
        try {
            setCommitMessage(getCommitMessage())
            setCommitAction('commit')
            setCommitDialogOpen(true)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not prepare worktree commit' })
        }
    }
    const handleIntegrateMenu = async () => {
        handleClose()
        try {
            if (assignmentTarget.kind === 'card') {
                if (assignedRecord?.status.dirty) setCommitMessage(getCommitMessage())
                setIntegrationDialogOpen(true)
                return
            }
            if (assignedRecord?.status.dirty) {
                setCommitMessage(getCommitMessage())
                setCommitAction('integrate')
                setCommitDialogOpen(true)
                return
            }
            await worktreeService.integrateProjectWorktree()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not integrate worktree into project' })
        }
    }
    const handleViewDiffMenu = () => {
        try {
            if (assignmentTarget.kind !== 'card') throw new Error('Worktree diff requires a card assignment')
            if (!anchorElement) throw new Error('Worktree diff requires a card popup anchor')
            if (!canIntegrate) throw new Error('Card worktree has no changes to integrate')
            const popupAnchorElement = anchorElement
            handleClose()
            cardBodyPopoverService.openWorktreeDiff(assignmentTarget.path, popupAnchorElement)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not open worktree diff' })
        }
    }
    const handleUpdateMenu = async () => {
        handleClose()
        try {
            if (assignedRecord?.status.dirty) {
                setCommitMessage(getCommitMessage())
                setCommitAction('update')
                setCommitDialogOpen(true)
                return
            }
            if (assignmentTarget.kind === 'card') await worktreeService.updateCardWorktree(assignmentTarget.path)
            else await worktreeService.updateProjectWorktree()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Could not update worktree from ${baseName}` })
        }
    }
    const handleCommitDialogClose = () => setCommitDialogOpen(false)
    const handleCommit = async (message: string) => {
        try {
            if (assignmentTarget.kind === 'card') await worktreeService.commitCardWorktree(assignmentTarget.path, message)
            else await worktreeService.commitProjectWorktree(message)
            setCommitDialogOpen(false)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not commit worktree changes' })
            return
        }
        try {
            if (commitAction === 'integrate') {
                await worktreeService.integrateProjectWorktree()
            }
            if (commitAction === 'update') {
                if (assignmentTarget.kind === 'card') await worktreeService.updateCardWorktree(assignmentTarget.path)
                else await worktreeService.updateProjectWorktree()
            }
        } catch (error) {
            const fallbackMessage = commitAction === 'integrate'
                ? 'Changes were committed, but the worktree could not be integrated into the project'
                : `Changes were committed, but the worktree could not be updated from ${baseName}`
            dialogService.error(error, { fallbackMessage })
        }
    }
    const handleUnassignClose = () => setUnassignDialogOpen(false)
    const handleDropAndUnassign = async () => {
        if (assignmentTarget.kind !== 'card') return

        try {
            await worktreeService.discardAndUnassignCardWorktree(assignmentTarget.path)
            setUnassignDialogOpen(false)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not drop worktree changes' })
        }
    }
    const handleCommitIntegrateAndUnassign = async (message: string) => {
        if (assignmentTarget.kind !== 'card') return

        try {
            await worktreeService.commitCardWorktree(assignmentTarget.path, message)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not commit worktree changes' })
            return
        }

        try {
            await worktreeService.integrateCardWorktree(assignmentTarget.path, false)
        } catch (error) {
            setUnassignDialogOpen(false)
            dialogService.error(error, { fallbackMessage: 'Changes were committed, but the worktree could not be integrated into the project' })
            return
        }

        try {
            await worktreeService.setCardWorktree(assignmentTarget.path, null)
            setUnassignDialogOpen(false)
        } catch (error) {
            setUnassignDialogOpen(false)
            dialogService.error(error, { fallbackMessage: 'Changes were integrated, but the worktree could not be unassigned' })
        }
    }
    const handleIntegrationClose = () => setIntegrationDialogOpen(false)
    const handleDeleteBranchChange = (deleteBranch: boolean) => {
        configService.setReactPreference('react.deleteBranchAfterIntegration', deleteBranch)
    }
    const handleIntegration = async () => {
        if (assignmentTarget.kind !== 'card') return

        const commitBeforeIntegration = !!assignedRecord?.status.dirty
        if (commitBeforeIntegration) {
            if (commitMessage.trim().length === 0) return

            try {
                await worktreeService.commitCardWorktree(assignmentTarget.path, commitMessage)
            } catch (error) {
                dialogService.error(error, { fallbackMessage: 'Could not commit worktree changes' })
                return
            }
        }

        try {
            await worktreeService.integrateCardWorktree(assignmentTarget.path, deleteBranchPreference)
            setIntegrationDialogOpen(false)
        } catch (error) {
            const fallbackMessage = commitBeforeIntegration
                ? 'Changes were committed, but the worktree could not be integrated into the project'
                : 'Could not integrate worktree into project'
            dialogService.error(error, { fallbackMessage })
        }
    }

    const button = (
        <IconButton
            aria-label={label}
            disabled={selectorDisabled}
            onClick={handleOpen}
            size="small"
            sx={{
                border: 1,
                borderColor: state.error ? 'error.main' : hasWorktreeChanges ? 'warning.main' : 'divider',
                color: state.error ? 'error.main' : hasWorktreeChanges ? 'warning.main' : 'text.secondary',
                height: 26,
                p: 0,
                pointerEvents: 'auto',
                position: 'relative',
                width: 26,
            }}
        >
            <Box
                sx={{
                    alignItems: 'center',
                    display: 'flex',
                    height: '100%',
                    justifyContent: 'center',
                    // leave room on the right for the arrow gutter so the glyph stays optically centred
                    pr: hasWorktreeChanges ? '8px' : 0,
                    width: '100%',
                }}
            >
                {state.value === 'P' ? <SourceBranch sx={{ fontSize: 14 }} /> : (
                    <Typography component="span" sx={{ fontSize: 11, fontWeight: 700, lineHeight: 1 }}>
                        {state.value}
                    </Typography>
                )}
            </Box>
            {hasWorktreeChanges ? (
                <Box
                    sx={{
                        alignItems: 'center',
                        bottom: 0,
                        display: 'flex',
                        flexDirection: 'column',
                        justifyContent: 'center',
                        position: 'absolute',
                        right: 1,
                        top: 0,
                        width: 8,
                    }}
                >
                    {hasOutgoingChanges ? <ArrowUp sx={{ display: 'block', fontSize: 9 }} /> : null}
                    {hasIncomingChanges ? <ArrowDown sx={{ display: 'block', fontSize: 9 }} /> : null}
                </Box>
            ) : null}
        </IconButton>
    )

    return (
        <>
            <Tooltip title={tooltip}>{selectorDisabled ? <span>{button}</span> : button}</Tooltip>
            <Menu anchorEl={anchorElement} onClose={handleClose} open={!!anchorElement}>
                <MenuItem onClick={handlePrimary} selected={assignment.worktree === null && !assignment.worktreeError}>
                    Primary{primaryPath ? ` â€” ${primaryPath}` : ''}
                </MenuItem>
                {(hasActiveCardWorktree || hasActiveProjectWorktree) ? (
                    <>
                        <MenuItem disabled={!canCommit} onClick={handleCommitMenu}>Commit</MenuItem>
                        <MenuItem disabled={!hasIncomingChanges} onClick={handleUpdateMenu}>Update worktree</MenuItem>
                        {assignmentTarget.kind === 'card' ? (
                            <MenuItem disabled={!canIntegrate} onClick={handleViewDiffMenu}>View diff</MenuItem>
                        ) : null}
                        <MenuItem disabled={assignmentTarget.kind === 'card' ? !canIntegrate : !hasOutgoingChanges} onClick={handleIntegrateMenu}>
                            Integrate into project
                        </MenuItem>
                    </>
                ) : worktrees.map((record, index) => (record.valid ? (
                    <MenuItem
                        data-worktree={index + 1}
                        disabled={assignmentTarget.kind === 'card'
                            && !worktreeService.isWorktreeAvailableForCard(index + 1, assignmentTarget.path)}
                        key={`${index}-${record.path}`}
                        onClick={handleWorktree}
                        selected={assignment.worktree === index + 1}
                    >
                        {index + 1} â€” {record.path}
                    </MenuItem>
                ) : null))}
                {state.error ? <MenuItem disabled selected>{state.value} â€” {state.error}</MenuItem> : null}
            </Menu>
            <WorktreeCommitDialog
                action={commitAction}
                busy={preparing}
                message={commitMessage}
                onClose={handleCommitDialogClose}
                onCommit={handleCommit}
                onMessageChange={setCommitMessage}
                open={commitDialogOpen}
            />
            <WorktreeIntegrationDialog
                busy={preparing}
                commitMessage={assignedRecord?.status.dirty ? commitMessage : null}
                deleteBranch={deleteBranchPreference}
                onClose={handleIntegrationClose}
                onCommitMessageChange={setCommitMessage}
                onDeleteBranchChange={handleDeleteBranchChange}
                onIntegrate={handleIntegration}
                open={integrationDialogOpen}
            />
            <WorktreeUnassignDialog
                busy={preparing}
                commitMessage={commitMessage}
                onClose={handleUnassignClose}
                onCommitMessageChange={setCommitMessage}
                onCommitIntegrate={handleCommitIntegrateAndUnassign}
                onDrop={handleDropAndUnassign}
                open={unassignDialogOpen}
            />
        </>
    )
}

import {
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogContentText,
    DialogTitle,
    FormControlLabel,
    TextField,
    Typography,
} from '@mui/material'
import type { ChangeEvent } from 'react'

interface WorktreeIntegrationDialogProps {
    busy: boolean
    commitMessage: string | null
    deleteBranch: boolean
    onClose: () => void
    onCommitMessageChange: (message: string) => void
    onDeleteBranchChange: (deleteBranch: boolean) => void
    onIntegrate: () => Promise<void>
    open: boolean
}

/** Confirms card worktree integration and optional local branch cleanup. */
export function WorktreeIntegrationDialog(props: WorktreeIntegrationDialogProps) {
    const {
        busy,
        commitMessage,
        deleteBranch,
        onClose,
        onCommitMessageChange,
        onDeleteBranchChange,
        onIntegrate,
        open,
    } = props
    const handleCommitMessageChange = (event: ChangeEvent<HTMLInputElement>) => onCommitMessageChange(event.target.value)
    const handleDeleteBranchChange = (event: ChangeEvent<HTMLInputElement>) => onDeleteBranchChange(event.target.checked)
    const integrateDisabled = busy || commitMessage !== null && commitMessage.trim().length === 0

    return (
        <Dialog fullWidth maxWidth="xs" onClose={busy ? undefined : onClose} open={open}>
            <DialogTitle>Integrate into project</DialogTitle>
            <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 1, pt: 1 }}>
                <DialogContentText>Squash-merge card changes into project branch.</DialogContentText>
                {commitMessage !== null ? (
                    <>
                        <Typography color="text.secondary">Commit message</Typography>
                        <TextField
                            autoFocus
                            disabled={busy}
                            onChange={handleCommitMessageChange}
                            size="small"
                            value={commitMessage}
                        />
                    </>
                ) : null}
                <FormControlLabel
                    control={<Checkbox checked={deleteBranch} disabled={busy} onChange={handleDeleteBranchChange} />}
                    label="Delete branch"
                />
            </DialogContent>
            <DialogActions>
                <Button disabled={busy} onClick={onClose}>Cancel</Button>
                <Button disabled={integrateDisabled} onClick={onIntegrate} variant="contained">Integrate</Button>
            </DialogActions>
        </Dialog>
    )
}

