const path = require('node:path');
const { ActionCancellationError } = require('./action_cancellation_error');

function requireActionContext(context) {
    if (!context || typeof context !== 'object') throw new Error('Missing action context');

    return context;
}

function worktreeIndex(context) {
    if (context.worktree === undefined) return null;
    if (typeof context.worktree !== 'string' || !/^[1-9]\d*$/u.test(context.worktree)) {
        throw new Error(`Invalid worktree index: ${String(context.worktree)}`);
    }

    const index = Number.parseInt(context.worktree, 10);
    if (!Number.isSafeInteger(index)) throw new Error(`Invalid worktree index: ${context.worktree}`);

    return index;
}

class ActionWorktreeRunService {
    constructor(dependencies) {
        this.runLockStates = new Map();
        this.worktreeService = dependencies.worktreeService;
    }

    async execute(primaryProject, action, contextValue, runner) {
        const context = requireActionContext(contextValue);
        const resolution = await this.resolve(primaryProject, action, context);
        const result = await runner(resolution.runProject);

        return ActionWorktreeRunService.addRunMetadata(
            result,
            resolution.runProject,
            resolution.runWorktree,
        );
    }

    /** Run one complete action run while holding its card-scoped lock. */
    async runWithCardLock(primaryProject, contextValue, operation, options = {}) {
        const context = requireActionContext(contextValue);
        const cardKey = ActionWorktreeRunService.cardKey(primaryProject, context);
        if (cardKey === null) return operation();

        return this.withRunLock(cardKey, options, operation);
    }

    async resolve(primaryProject, action, context) {
        const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError;
        if (!hasWorktreeAssignment && !action.needsWorkTree) {
            return { runProject: primaryProject, runWorktree: null };
        }
        if (context.worktreeError) throw new Error(context.worktreeError);
        if (context.kind !== 'card' && context.kind !== 'project') {
            const reason = action.needsWorkTree
                ? 'when needsWorkTree is set'
                : 'for worktree run';
            throw new Error(`Action "${action.label}" requires card or project context ${reason}`);
        }

        const index = worktreeIndex(context);
        if (index === null) throw new Error(`Action "${action.label}" requires a worktree assignment`);

        const record = await this.worktreeService.resolve(primaryProject, index);

        return {
            runProject: { ...primaryProject, branch: record.branch, id: record.path, rootPath: record.path },
            runWorktree: index,
        };
    }

    async withRunLock(cardKey, options, operation) {
        const request = await this.acquireRunLock(cardKey, options);

        try {
            return await operation();
        } finally {
            this.releaseRunLock(cardKey, request);
        }
    }

    async acquireRunLock(cardKey, options) {
        const signal = options.signal;
        if (signal?.aborted) throw new ActionCancellationError('Action cancelled');

        const { promise, reject, resolve } = Promise.withResolvers();
        const state = this.runLockStates.get(cardKey) ?? { activeRequest: null, pending: [] };
        const request = { acquired: false, abortHandler: null, reject, resolve, signal };
        request.abortHandler = this.cancelLockRequest.bind(this, cardKey, request);
        signal?.addEventListener('abort', request.abortHandler, { once: true });
        state.pending.push(request);
        this.runLockStates.set(cardKey, state);
        ActionWorktreeRunService.drainRunLocks(state);
        if (!request.acquired) options.onQueued?.();
        await promise;

        return request;
    }

    cancelLockRequest(cardKey, request) {
        const state = this.runLockStates.get(cardKey);
        if (!state || request.acquired) return;

        const requestIndex = state.pending.indexOf(request);
        if (requestIndex < 0) return;

        state.pending.splice(requestIndex, 1);
        request.signal?.removeEventListener('abort', request.abortHandler);
        request.reject(new ActionCancellationError('Action cancelled'));
        ActionWorktreeRunService.drainRunLocks(state);
        this.deleteEmptyLockState(cardKey, state);
    }

    releaseRunLock(cardKey, request) {
        const state = this.runLockStates.get(cardKey);
        if (!state) throw new Error('Missing action run lock state');
        if (state.activeRequest !== request) throw new Error('Invalid active action run lock');

        state.activeRequest = null;
        ActionWorktreeRunService.drainRunLocks(state);
        this.deleteEmptyLockState(cardKey, state);
    }

    deleteEmptyLockState(cardKey, state) {
        if (!state.activeRequest && state.pending.length === 0) this.runLockStates.delete(cardKey);
    }

    static drainRunLocks(state) {
        if (state.activeRequest || state.pending.length === 0) return;

        const request = state.pending.shift();
        request.acquired = true;
        state.activeRequest = request;
        request.signal?.removeEventListener('abort', request.abortHandler);
        request.resolve();
    }

    static cardKey(primaryProject, context) {
        if (typeof context.cardInternalId !== 'string' || context.cardInternalId.length === 0) return null;

        const repositoryKey = path.resolve(primaryProject.rootPath).toLowerCase();

        return `${repositoryKey}\0${context.cardInternalId}`;
    }

    static addRunMetadata(result, project, runWorktree) {
        return { ...result, branch: project.branch, runWorktree, repositoryRoot: project.rootPath };
    }
}

module.exports = { ActionWorktreeRunService, worktreeIndex };

const crypto = require('node:crypto');
const { ActionAgentExecutor } = require('./action_agent_executor');
const { runCommand } = require('./action_command_executor');
const { ActionDefinitionCache } = require('./action_definition_cache');
const { resolveActionDefinition } = require('./action_definition_resolver');
const { ActionRun } = require('./action_run');
const { prepareAgentPrompt } = require('./action_text');
const { validatePreparePromptRequest, validateStartRequest } = require('./action_run_request');
const { assertReleasedCardActionAllowed } = require('../../../../shared/released_card_actions.mjs');

function createRunId() {
    return `action-${crypto.randomUUID()}`;
}

function activityOrigin(context) {
    if (context.kind === 'card' || context.kind === 'file') {
        if (typeof context.cardInternalId !== 'string' || context.cardInternalId.length === 0) {
            throw new Error('Card-origin action requires cardInternalId');
        }

        return { cardInternalId: context.cardInternalId, kind: 'card' };
    }

    return { kind: 'project' };
}

function hasStreamingAction(action, visited = new Set()) {
    if (visited.has(action.id)) return false;
    visited.add(action.id);
    if (action.type === 'agent' && action.streaming) return true;

    return [...action.onBefore, ...action.onAfter, ...action.on.map(({ action: linkedAction }) => linkedAction)]
        .some((linkedAction) => hasStreamingAction(linkedAction, visited));
}

class ActionRunnerService {
    constructor(dependencies) {
        this.actionWorktreeRunService = dependencies?.actionWorktreeRunService;
        this.agentConfigProvider = dependencies?.agentConfigProvider;
        this.agentRunnerService = dependencies?.agentRunnerService;
        this.commandRunner = dependencies?.commandRunner ?? runCommand;
        this.errorReporter = dependencies?.errorReporter ?? (() => undefined);
        this.localGitService = dependencies?.localGitService;
        this.actionDefinitionCache = dependencies?.actionDefinitionCache
            ?? (this.localGitService ? new ActionDefinitionCache({ localGitService: this.localGitService }) : null);
        this.agentExecutor = new ActionAgentExecutor({
            agentConfigProvider: this.agentConfigProvider,
            agentRunnerService: this.agentRunnerService,
            localGitService: this.localGitService,
        });
        this.actionsFolder = null;
        this.actionCacheReady = null;
        this.completedRunResults = new Map();
        this.conversationReservations = new Map();
        this.configuredStates = [];
        this.runEvents = new Map();
        this.runs = new Map();
        this.listeners = new Set();
        this.project = null;
        this.projectFolder = null;
        this.releasesFolder = null;
        this.restartingRuns = new Set();
    }

    async startProject(project, actionsFolder, projectFolder, releasesFolder) {
        if (typeof projectFolder !== 'string') throw new Error('Missing action runner projectFolder');
        if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) throw new Error('Missing action runner releasesFolder');
        if (this.project) await this.stop();
        this.project = project;
        this.actionsFolder = actionsFolder;
        this.projectFolder = projectFolder;
        this.releasesFolder = releasesFolder;
        this.actionCacheReady = this.actionDefinitionCache && this.localGitService
            ? this.initializeProject(project, actionsFolder)
            : null;

        return this.actionCacheReady ?? Promise.resolve();
    }

    async initializeProject(project, actionsFolder) {
        const [, config] = await Promise.all([
            this.actionDefinitionCache.startProject(project, actionsFolder),
            this.localGitService.loadProjectConfig(project),
        ]);
        const states = config?.states;
        if (!Array.isArray(states)) throw new Error('Invalid project states');
        this.configuredStates = states.map(({ state }) => {
            if (typeof state !== 'string' || state.length === 0) throw new Error('Invalid project state');

            return state;
        });
    }

    async stop() {
        const completions = [...this.runs.values()].map((run) => {
            run.cancel();

            return run.completion;
        });
        await Promise.all(completions);
        this.clearProject();
    }

    async suspend() {
        const completions = [...this.runs.values()].map((run) => {
            run.suspend();

            return run.completion;
        });
        await Promise.all(completions);
        this.clearProject();
    }

    clearProject() {
        this.project = null;
        this.actionsFolder = null;
        this.actionCacheReady = null;
        this.projectFolder = null;
        this.releasesFolder = null;
        this.configuredStates = [];
        this.conversationReservations.clear();
        this.actionDefinitionCache?.stop();
    }

    subscribe(listener) {
        if (typeof listener !== 'function') throw new Error('Missing action run listener');
        this.listeners.add(listener);

        return () => this.listeners.delete(listener);
    }

    async start(request, options = {}) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        const origin = activityOrigin(startRequest.context);
        const project = { ...this.project };
        const actionsFolder = this.actionsFolder;
        const rootAction = await this.loadRootAction(startRequest.actionId);
        if (options.interactive === false && hasStreamingAction(rootAction)) {
            throw new Error(`Streaming action requires an interactive manual run: ${rootAction.label}`);
        }
        const conversationReservation = this.consumeConversationReservation(startRequest, rootAction);
        const runId = createRunId();
        const run = new ActionRun({
            actionsFolder,
            activityOrigin: origin,
            context: startRequest.context,
            conversationReservation,
            runId,
            project,
            projectFolder: this.projectFolder,
            releasesFolder: this.releasesFolder,
            rootAction,
            runInput: startRequest.runInput,
            startedAt: new Date().toISOString(),
        }, {
            actionWorktreeRunService: this.actionWorktreeRunService,
            agentExecutor: this.agentExecutor,
            agentRunnerService: this.agentRunnerService,
            commandRunner: this.commandRunner,
            localGitService: this.localGitService,
            publisher: this.publish.bind(this),
        });
        this.runEvents.set(runId, []);
        this.runs.set(runId, run);
        run.start(this.finalizeRun.bind(this, run));

        return runId;
    }

    async reserveConversation(request) {
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        if (startRequest.runInput.continueFrom) throw new Error('Continuing an agent conversation does not require a reservation');
        const action = await this.loadRootAction(startRequest.actionId);
        if (action.type !== 'agent') throw new Error('Cannot reserve a conversation for a command action');
        const origin = activityOrigin(startRequest.context);
        const project = { ...this.project };
        const conversationId = `agent-${crypto.randomUUID()}`;
        const reference = this.localGitService.activityConversationReference(this.projectFolder, origin, conversationId);
        await this.localGitService.ensureActivityFile(project, this.projectFolder, origin);
        const reservation = { conversationId, reference };
        this.conversationReservations.set(reference, reservation);

        return reservation;
    }

    consumeConversationReservation(startRequest, rootAction) {
        const reservation = startRequest.conversationReservation;
        if (!reservation) return null;
        if (rootAction.type !== 'agent') throw new Error('Command action cannot use an agent conversation reservation');
        const stored = this.conversationReservations.get(reservation.reference);
        if (!stored || stored.conversationId !== reservation.conversationId) {
            throw new Error('Unknown agent conversation reservation');
        }
        this.conversationReservations.delete(reservation.reference);

        return reservation;
    }

    async prepareActionPrompt(request) {
        const promptRequest = validatePreparePromptRequest(request);
        this.requirePreparationReady();
        assertReleasedCardActionAllowed(promptRequest.context, this.releasesFolder);
        const project = { ...this.project };
        const action = await this.loadRootAction(promptRequest.actionId);
        if (action.type !== 'agent') throw new Error('Cannot prepare a prompt for a command action');
        const resolution = await this.actionWorktreeRunService.resolve(project, action, promptRequest.context);

        return {
            prompt: prepareAgentPrompt(
                action,
                promptRequest.context,
                resolution.runProject,
                project,
                this.projectFolder,
                this.releasesFolder,
            ),
        };
    }

    async wait(runId) {
        const run = this.runs.get(runId);
        if (run) return run.completion;

        const result = this.completedRunResults.get(runId);
        if (!result) throw new Error(`Unknown action run: ${runId}`);
        this.completedRunResults.delete(runId);

        return result;
    }

    async restart(runId, request) {
        if (this.restartingRuns.has(runId)) throw new Error(`Action run restart already in progress: ${runId}`);
        const startRequest = validateStartRequest(request);
        this.requireReady();
        assertReleasedCardActionAllowed(startRequest.context, this.releasesFolder);
        const run = this.requireRun(runId);
        this.restartingRuns.add(runId);
        try {
            run.finishAgent();
            const result = await run.completion;
            if (result.status !== 'completed') {
                throw new Error(result.failure ?? `Action run could not be restarted after ${result.status}`);
            }

            return await this.start(request);
        } finally {
            this.restartingRuns.delete(runId);
        }
    }

    loadActiveRunEvents() {
        return [...this.runEvents.values()].flatMap((events) => events.map((event) => structuredClone(event)));
    }

    cancel(runId) {
        this.requireRun(runId).cancel();
    }

    sendAgentMessage(runId, content) {
        return this.requireRun(runId).sendAgentMessage(content);
    }

    beginAgentPromptDraft(runId) {
        return this.requireRun(runId).beginAgentPromptDraft();
    }

    setAgentQueuedMessage(runId, sessionId, content, revision) {
        return this.requireRun(runId).setAgentQueuedMessage(sessionId, content, revision);
    }

    sendQueuedAgentMessage(runId, sessionId, revision) {
        return this.requireRun(runId).sendQueuedAgentMessage(sessionId, revision);
    }

    answerAgentQuestion(runId, requestId, answers) {
        return this.requireRun(runId).answerAgentQuestion(requestId, answers);
    }

    answerAgentApproval(runId, requestId, decision) {
        return this.requireRun(runId).answerAgentApproval(requestId, decision);
    }

    finishAgentRun(runId) {
        this.requireRun(runId).finishAgent();
    }

    handleCardStateChange(cardInternalId, state) {
        for (const run of this.runs.values()) run.handleCardStateChange(cardInternalId, state);
    }

    requireActionsFolder() {
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');

        return this.actionsFolder;
    }

    requireProjectFolder() {
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (this.releasesFolder === null) throw new Error('Action runner has no releasesFolder');

        return this.projectFolder;
    }

    async loadRootAction(actionId) {
        const config = this.agentConfigProvider();
        await this.actionCacheReady;

        return resolveActionDefinition(this.actionDefinitionCache, config.agentProfiles, actionId, this.configuredStates);
    }

    async finalizeRun(run, runCompletion) {
        const result = await runCompletion;
        this.runs.delete(run.runId);
        this.runEvents.delete(run.runId);
        this.completedRunResults.set(run.runId, result);
        return result;
    }

    publish(event) {
        const events = this.runEvents.get(event.runId);
        if (events) events.push(event);
        for (const listener of this.listeners) {
            try {
                listener(event);
            } catch (error) {
                this.reportError(error);
            }
        }
    }

    reportError(error) {
        try {
            this.errorReporter(error);
        } catch {
            // Error reporting must not affect action runs.
        }
    }

    requireRun(runId) {
        const run = this.runs.get(runId);
        if (!run) throw new Error(`Unknown action run: ${runId}`);

        return run;
    }

    requireReady() {
        this.requirePreparationReady();
        if (!this.agentRunnerService) throw new Error('Action runner has no agent runner service');
    }

    requirePreparationReady() {
        if (!this.project) throw new Error('Action runner has no project');
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (!this.localGitService) throw new Error('Action runner has no local Git service');
        if (!this.actionDefinitionCache) throw new Error('Action runner has no action definition cache');
        if (!this.actionCacheReady) throw new Error('Action runner action definition cache is not ready');
        if (!this.actionWorktreeRunService) throw new Error('Action runner has no worktree run service');
        if (!this.agentConfigProvider) throw new Error('Action runner has no agent config provider');
    }
}

module.exports = { ActionRunnerService };

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { AgentConversationReservation, ActionRunInput, ActionRunResult } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { actionRunRegistry, cancelActionRun } from './action_run_registry'
import { dataService } from '../data/data_service'
import { projectPersistenceService } from '../project/project_persistence_service'

function shouldReserveConversation(action: ActionDefinition, context: ActionContext, input: ActionRunInput) {
    return action.type === 'agent'
        && !input.continueFrom
        && (context.kind === 'card' || context.kind === 'file')
        && !!context.cardInternalId
        && !!context.file
}

/** Start one persisted action through shared renderer run state. */
export async function runElectronAction(
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput = {},
    onStarted?: (runId: string) => void,
    interactive = true,
): Promise<ActionRunResult> {
    const handleStarted = (startedRunId: string) => {
        onStarted?.(startedRunId)
    }
    const requiresReservation = shouldReserveConversation(action, context, input)
    const bridge = getElectronActionBridge()
    const resumeAutomaticCommit = requiresReservation ? dataService.cards.deferAutomaticCommit() : null
    let conversationReservation: AgentConversationReservation | undefined
    try {
        conversationReservation = requiresReservation
            ? await bridge?.reserveActionConversation?.({ actionId: action.id, context, runInput: input })
            : undefined
        if (requiresReservation && !conversationReservation) {
            throw new Error('Starting a card agent requires conversation reservation support')
        }
        if (conversationReservation && context.file) {
            dataService.cards.addAgentLogReference(context.file, conversationReservation.reference)
        }
    } finally {
        resumeAutomaticCommit?.()
    }
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
    return actionRunRegistry.startRun(action, context, input, handleStarted, interactive, conversationReservation)
}

/** Finish one idle streaming run, persist it, then continue through a new process. */
export async function restartElectronAction(
    previousRunId: string,
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput,
    onStarted?: (runId: string) => void,
): Promise<ActionRunResult> {
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()

    return actionRunRegistry.restartRun(previousRunId, action, context, input, onStarted)
}

export async function cancelElectronAction(runId: string) {
    await cancelActionRun(runId)
}

import { IconButton, ListItemIcon, MenuItem, Stack, Tooltip } from '@mui/material'
import { useEffect, useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { displayActionsForContext, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { dialogService } from '../../../../services/dialog_service'
import { useActions } from '../../../hooks/use_actions'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { ActionIcon } from './action_icon'
import { resolveActionIcon, type ActionIconSource } from './action_icon_resolver'
import { ActionPopup } from '../popup/action_popup'

/** How action entry points are rendered in an existing toolbar or menu. */
export type ActionEntryVariant = 'icons' | 'menuItems'
export type ActionEntryVisibility = 'all-matching' | 'explicit-context'

interface ActionEntryPointsProps {
    context: ActionContext
    onMenuItemSelected?: () => void
    popupAnchorElement?: HTMLElement | null
    variant: ActionEntryVariant
    visibility?: ActionEntryVisibility
}

const DEFAULT_ICON_SOURCE: ActionIconSource = { dataUri: null }

interface ActionPopupState {
    actionId: string
    anchorElement: HTMLElement
}

/**
 * Context-sensitive action entry points shown close to a card/file/folder. Filters
 * the loaded actions by `appliesTo`, and on activation opens a resizable popup bound
 * to the action and context. `before`/`after` shortcuts push a new popup for the
 * related action with the same context.
 */
export function ActionEntryPoints(props: ActionEntryPointsProps) {
    const { context, onMenuItemSelected, popupAnchorElement, variant, visibility = 'all-matching' } = props
    const { actions: loadedActions } = useActions()
    const runningRun = useRunningActionForContext(context)
    const runDisabled = !!runningRun
    const [iconSources, setIconSources] = useState<Record<string, ActionIconSource>>({})
    const [popupState, setPopupState] = useState<ActionPopupState | null>(null)

    const matching = useMemo(() => {
        const contextActions = displayActionsForContext(loadedActions, context)
        if (visibility === 'explicit-context') {
            return contextActions.filter((action) => action.appliesTo?.kind === context.kind)
        }

        return contextActions
    }, [context, loadedActions, visibility])

    useEffect(() => {
        let isActive = true

        const loadIcons = async () => {
            const entries = await Promise.all(matching.map(async (action) => [action.id, await resolveActionIcon(action.icon)] as const))
            if (!isActive) return

            setIconSources(Object.fromEntries(entries))
        }

        void loadIcons()

        return () => {
            isActive = false
        }
    }, [matching])

    if (matching.length === 0) return null

    const open = (actionId: string, anchorElement: HTMLElement) => {
        onMenuItemSelected?.()
        setPopupState({ actionId, anchorElement })
    }

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        try {
            const { actionId } = event.currentTarget.dataset
            if (!actionId) throw new Error('Missing action id on action entry point')

            open(actionId, popupAnchorElement ?? event.currentTarget)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action popup could not be opened' })
        }
    }

    const iconSourceFor = (action: ActionDefinition) => iconSources[action.id] ?? DEFAULT_ICON_SOURCE

    const closePopup = () => {
        setPopupState(null)
    }

    const popup = popupState ? (
        <ActionPopup
            anchorElement={popupState.anchorElement}
            context={context}
            draggable
            initialActionId={popupState.actionId}
            key={popupState.actionId}
            onClose={closePopup}
        />
    ) : null

    const menuItems = (
        <>
            {matching.map((action) => (
                <MenuItem
                    data-action-id={action.id}
                    disabled={runDisabled}
                    key={action.id}
                    onClick={handleOpen}
                >
                    <ListItemIcon>
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </ListItemIcon>
                    {action.label}
                </MenuItem>
            ))}
            {popup}
        </>
    )

    if (variant === 'menuItems') return menuItems

    return (
        <Stack direction="row" spacing={0.25} sx={{ flexShrink: 0 }}>
            {matching.map((action) => (
                <Tooltip key={action.id} title={action.label}>
                    <IconButton
                        aria-label={action.label}
                        data-action-id={action.id}
                        disabled={runDisabled}
                        onClick={handleOpen}
                        size="small"
                    >
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </IconButton>
                </Tooltip>
            ))}
            {popup}
        </Stack>
    )
}

